import overcrow from './overcrow.js';

const cpu = document.createElement('p');
const fps = document.createElement('p');
document.body.append(cpu, fps);

function show(element, snapshot, value, stale, age) {
  const message = value ?? `Measurement unavailable (${snapshot.status})`;
  element.textContent = message + (stale ? ` · stale (${age ?? 'unknown'} ms old)` : '');
}

const stopCpu = overcrow.telemetry.onSnapshot(snapshot => {
  const value = snapshot.data?.normalizedCpuPercentHundredths;
  show(cpu, snapshot, value == null ? null : `${value / 100}% CPU`,
    snapshot.status === 'stale', snapshot.sampleAgeMs);
});
const stopFps = overcrow.fps.onSnapshot(snapshot => {
  const data = snapshot.data;
  show(fps, snapshot, data?.value == null ? null : `${data.value} FPS`,
    snapshot.status === 'stale' || data?.stale === true,
    data?.sampleAgeMs ?? snapshot.sampleAgeMs);
});
window.addEventListener('pagehide', () => { stopCpu(); stopFps(); }, {once: true});

