import overcrow from './overcrow.js';

const time = document.createElement('p');
document.body.append(time);
const stop = overcrow.stopwatch.onSnapshot(snapshot => {
  const data = snapshot.data;
  time.textContent = data
    ? `${Math.floor(data.elapsedMs / 1000)} s · ${data.running ? 'running' : 'paused'}`
    : snapshot.status;
  if (snapshot.status === 'stale') {
    time.textContent += ` · stale (${snapshot.sampleAgeMs ?? 'unknown'} ms old)`;
  }
});
window.addEventListener('pagehide', stop, {once: true});

