import overcrow from './overcrow.js';

const note = document.createElement('pre');
const status = document.createElement('p');
const create = document.createElement('button');
create.textContent = 'New note in OverCrow';
create.disabled = true;
document.body.append(note, status, create);
let current = null;

const stop = overcrow.notes.onSnapshot(snapshot => {
  current = snapshot.status === 'ready' ? snapshot : null;
  const active = snapshot.data?.notes.find(item => item.id === snapshot.data.activeNoteId);
  note.textContent = active ? `${active.title}\n${active.body}`
    : snapshot.data ? 'No active note' : snapshot.status;
  status.textContent = snapshot.status === 'stale'
    ? `Stale (${snapshot.sampleAgeMs ?? 'unknown'} ms old)`
    : snapshot.data?.saveState ?? snapshot.status;
  create.disabled = !current;
});
create.addEventListener('click', async () => {
  if (!current) return;
  try {
    const result = await overcrow.notes.requestCreate({
      expectedRevision: current.data.documentRevision,
    });
    status.textContent = result.status;
  } catch (error) {
    status.textContent = error.code ?? 'unavailable';
  }
});
window.addEventListener('pagehide', stop, {once: true});

