      "journal.local.read"
    ]
  }
}

import overcrow from './overcrow.js';

const status = document.createElement('p');
const list = document.createElement('ul');
const next = document.createElement('button');
next.textContent = 'Next page';
next.disabled = true;
document.body.append(status, list, next);
let nextCursor = null;

const stop = overcrow.journal.onSnapshot(snapshot => {
  const data = snapshot.data;
  status.textContent = snapshot.status === 'stale'
    ? `Stale (${snapshot.sampleAgeMs ?? 'unknown'} ms old)` : snapshot.status;
  list.replaceChildren(...(data?.sessions ?? []).map(session => {
    const item = document.createElement('li');
    item.textContent = `${session.startedAt} · ${session.durationMs / 1000} s · ${session.source}`
      + (session.interrupted ? ' · interrupted' : '');
    return item;
  }));
  nextCursor = snapshot.status === 'ready' ? data.nextCursor : null;
  next.disabled = nextCursor === null;
});
next.addEventListener('click', async () => {
  if (nextCursor === null) return;
  try {
    status.textContent = (await overcrow.journal.page({cursor: nextCursor})).status;
  } catch (error) {
    status.textContent = error.code ?? 'unavailable';
  }
});
window.addEventListener('pagehide', stop, {once: true});

