import overcrow from './overcrow.js';

const chat = document.createElement('pre');
document.body.append(chat);
const stop = overcrow.twitch.chat.onSnapshot(snapshot => {
  const data = snapshot.data;
  const heading = data
    ? `${data.channelDisplayName ?? 'No channel'} · ${data.connection}` : snapshot.status;
  const age = snapshot.status === 'stale'
    ? ` · stale (${snapshot.sampleAgeMs ?? 'unknown'} ms old)` : '';
  const messages = (data?.messages ?? []).map(message =>
    `${message.displayName}: ${message.text}`).join('\n');
  chat.textContent = `${heading}${age}\n${messages}`;
});
window.addEventListener('pagehide', stop, {once: true});

